s = p.read_text().replace('assert.equal(manifest.version, "1.8.0-qa.2");', 'assert.match(manifest.version, /^1\\.8\\.0-qa\\.\\d+$/);')
p.write_text(s)

# Dedicated M6 handoff smoke.
Path('qa/m6-conflict-live-handoff-smoke.mjs').write_text('''import assert from "node:assert/strict";\nimport { evaluateM6ConflictResolutionLiveHandoff, getM6ConflictLiveHandoffStatus, resetM6ConflictHandoffTelemetry, setM6CoreResolutionEnabled } from "../module/m6-conflict-live-handoff.mjs";\n\nresetM6ConflictHandoffTelemetry();\nsetM6CoreResolutionEnabled(true);\nlet result = evaluateM6ConflictResolutionLiveHandoff({\n  conflictId: "qa", exchange: 1, actionIndex: 0, gmAction: "attack", rangerAction: "defend", gmMode: "versus", rangerMode: "versus",\n  gmRoll: { successes: 4 }, rangerRoll: { successes: 2 },\n  legacy: { gmPassed: true, rangerPassed: false, gmMargin: 2, rangerMargin: 0, gmFailureMargin: 0, rangerFailureMargin: 2, gmEffectiveSuccesses: 4, rangerEffectiveSuccesses: 2, tiePending: false }\n});\nassert.equal(result.m6.resolutionAuthority, "CORE_M6"); assert.equal(result.gmMargin, 2);\nlet status = getM6ConflictLiveHandoffStatus(); assert.equal(status.telemetry.matches, 1); assert.equal(status.telemetry.mismatches, 0);\n\nresult = evaluateM6ConflictResolutionLiveHandoff({\n  conflictId: "qa", exchange: 1, actionIndex: 1, gmAction: "attack", rangerAction: "defend", gmMode: "versus", rangerMode: "versus",\n  gmRoll: { successes: 4 }, rangerRoll: { successes: 2 },\n  legacy: { gmPassed: false, rangerPassed: true, gmMargin: 0, rangerMargin: 1, gmFailureMargin: 1, rangerFailureMargin: 0, gmEffectiveSuccesses: 4, rangerEffectiveSuccesses: 2, tiePending: false }\n});\nassert.equal(result.m6.resolutionAuthority, "LEGACY_FALLBACK");\nstatus = getM6ConflictLiveHandoffStatus(); assert.equal(status.enabled, false); assert.equal(status.rollbackReason, "RESOLUTION_DISAGREEMENT"); assert.equal(status.telemetry.mismatches, 1);\n\nsetM6CoreResolutionEnabled(true); resetM6ConflictHandoffTelemetry();\nconsole.log("PASS m6-conflict-live-handoff-smoke");\n''')

Path('TEST_PROTOCOL_v1.8.0-qa.3.md').write_text('''# Realm Guard / Torchbearer v1.8.0-qa.3 QA Protocol\n\n## Scope\nFirst controlled M6 live handoff. CORE becomes live authority only for the completed action-pair resolution result fields: pass/fail, margin, failure margin and effective successes. Legacy Mixed still owns every Conflict state write, disposition mutation, Learning/Nature writes, Maneuver state, exchange advancement and compromise flow. Legacy calculates the result independently first and acts as a parity guard. Any disagreement or CORE exception automatically disables the handoff and uses Legacy immediately.\n\n## 1. Initial status\n```js\ngame.system.version\ngame.realmGuard.core.m6.getStatus()\ngame.realmGuard.core.m6.handoffStatus()\n```\nExpected: `1.8.0-qa.3`; `liveApplication:true`; mode `CORE_RESOLUTION_LEGACY_STATE`; handoff enabled; resolutionAuthority `CORE_M6`; conflictStateAuthority `LEGACY_MIXED`; rollbackReason empty.\n\n## 2. Reset telemetry\n```js\ngame.realmGuard.core.m6.clear()\ngame.realmGuard.core.m6.resetHandoffTelemetry()\n```\n\n## 3. Normal Versus\nResolve Attack vs Defend with unequal effective successes. Then:\n```js\ngame.realmGuard.core.m6.handoffHistory().slice(-3)\ngame.realmGuard.core.m6.getStatus()\n```\nExpected latest handoff event `CORE_RESOLUTION_APPLIED`, parityGuard `MATCH`, resolutionAuthority `CORE_M6`. Shadow resolution remains `MATCH`; no gameplay/UI change.\n\n## 4. Independent\nResolve an Independent pair. Expected `CORE_RESOLUTION_APPLIED`, no mismatch.\n\n## 5. Automatic Versus tie\nResolve an equal Versus result that completes through the automatic tiebreak. Expected `CORE_RESOLUTION_APPLIED`; winner/margin and final disposition identical to Legacy; no mismatch.\n\n## 6. Maneuver\nResolve a successful Maneuver with margin > 0 and complete the normal Maneuver choice. Expected CORE result applied while Legacy still owns Maneuver queue/state/write.\n\n## 7. Manual rollback\n```js\ngame.realmGuard.core.m6.rollback("QA_MANUAL_ROLLBACK")\ngame.realmGuard.core.m6.handoffStatus()\n```\nExpected enabled false, mode `LEGACY_ROLLBACK`, resolutionAuthority `LEGACY_MIXED`, reason `QA_MANUAL_ROLLBACK`. Resolve one action pair; gameplay must work normally and handoff history records `LEGACY_ROLLBACK`.\n\nRe-enable:\n```js\ngame.realmGuard.core.m6.enableCoreResolution()\ngame.realmGuard.core.m6.resetHandoffTelemetry()\ngame.realmGuard.core.m6.clear()\n```\n\n## 8. Final regression\nResolve at least one complete action pair/exchange. Verify Conflict Tool bonuses, Token Actor resolution, Learning/Nature handling, disposition, chat, Maneuver UI and exchange flow remain unchanged.\n\nFinal checks:\n```js\ngame.realmGuard.core.m6.handoffStatus()\ngame.realmGuard.core.m6.getStatus()\n```\nPASS: enabled true; telemetry mismatches 0; errorFallbacks 0; rollbackReason empty; shadow mismatches 0; latest live handoff `CORE_RESOLUTION_APPLIED`.\n''')

Path('release/NOTES.md').write_text('''Realm Guard / Torchbearer v1.8.0-qa.3 — first controlled M6 Conflict resolution live handoff.\n\nAfter qa.2 verified 18/18 M6 shadow observations with zero mismatches, CORE now becomes live authority for a deliberately narrow result scope: completed action-pair pass/fail, margins, failure margins and effective successes.\n\nLegacy Mixed still computes independently first as a parity guard and remains the sole authority for Conflict state writes, disposition mutation, Learning/Nature writes, Maneuver state, exchange advancement and compromise flow. Any CORE exception or result disagreement immediately falls back to Legacy and disables the handoff for the session. Manual rollback/re-enable APIs are exposed under game.realmGuard.core.m6.\n\nAll previous M5 live handoffs and qa.22 Token Actor resolution remain unchanged.\n\nQA protocol: TEST_PROTOCOL_v1.8.0-qa.3.md\n''')
